    const payload: TypeformWebhookPayload = SOURCE_EXAMPLE as unknown as TypeformWebhookPayload;
    const config: ConnectorConfig = {
      brevoApiKey: 'key',
      emailFieldId: 'SMEUb7VJz92Q',
      nameFieldId: '',
