  it('throws descriptive error when brevoListId is missing', async () => {
    const { fetch } = fakeFetch((req) => jsonResponse({ id: 1 }, 201));

    const payload: TypeformWebhookPayload = SOURCE_EXAMPLE as unknown as TypeformWebhookPayload;
    const config: ConnectorConfig = {
      brevoApiKey: 'key',
      emailFieldId: 'SMEUb7VJz92Q',
      nameFieldId: 'JwWggjAKtOkA',
