  it('throws with status code and endpoint on non-2xx response', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://api.brevo.com/v3/contacts' && req.method === 'POST'
        ? jsonResponse({ code: 'duplicate_parameter', message: 'Contact already exists' }, 400)
        : jsonResponse({ error: 'not found' }, 404),
    );

    const payload: TypeformWebhookPayload = {
      event_id: 'evt-6',
      event_type: 'form_response',
      form_response: {
        form_id: 'form-6',
        token: 'tok-6',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
